Lemma Z_iter_ind {A} (f : A -> A) (P : Z -> A -> Prop) x :
  P 0 x -> (forall n y, 0 <= n -> P n y -> P (n + 1) (f y)) ->
  forall n, 0 <= n -> P n (Z.iter n f x).
