Lemma del_slots_lookup p stride cnt st s x : 0 <= cnt ->
  (s_slots (del_slots p stride cnt st)) !! s = Some x <->
  (s_slots st) !! s = Some x /\ forall i, 0 <= i < cnt -> s <> aadd p (UNIT + stride * i).
Proof.
