Lemma KINV_fm : forall st LB c g,
  KINV st LB c -> meta_slot st g -> ~ is_gm st g ->
  m_next (get_meta_rec st g) = None ->
  (forall s j, (s_slots st) !! s <> Some (g, j)) ->
  KINV (fm_st st g) LB c.
Proof.
